bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
printf 'ACTIVE_IMAGE='
docker inspect "$cid" --format '{{.Config.Image}}'
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg'; import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,
 database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
try {
 const owners=await pool.query('SELECT seller_user_id FROM videobot_listings WHERE listing_id=$1',['v26nov24invoice']);
 if(owners.rows.length!==1)throw Error('OWNER_ANCHOR_UNKNOWN');
 const owner=owners.rows[0].seller_user_id;
 const listings=await pool.query(
  `SELECT l.listing_id,l.revision,l.status,l.title,l.created_at,
    (SELECT COUNT(*)::int FROM videobot_stars_ledger s WHERE s.listing_id=l.listing_id AND s.kind='paid') AS paid_count,
    (SELECT COUNT(*)::int FROM videobot_video_invoice_orders o WHERE o.listing_id=l.listing_id AND o.status IN ('paid','delivering','delivered','delivery_unknown')) AS invoice_paid_count,
    (SELECT COUNT(*)::int FROM videobot_video_invoice_orders o WHERE o.listing_id=l.listing_id) AS invoice_order_count,
    (SELECT COUNT(*)::int FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id AND r.status='sent') AS public_receipt_count,
    (SELECT COUNT(*)::int FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id) AS receipt_count,
    (SELECT COALESCE(array_agg(r.paid_message_id) FILTER(WHERE r.paid_message_id IS NOT NULL),ARRAY[]::bigint[]) FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id) AS post_ids
    FROM videobot_listings l WHERE l.seller_user_id=$1 ORDER BY l.created_at DESC LIMIT 30`,[owner]);
 const sessions=await pool.query('SELECT revision,state FROM videobot_creator_sessions WHERE owner_user_id=$1',[owner]);
 const sameTitle=await pool.query(
  `SELECT COUNT(*)::int AS n FROM videobot_listings WHERE seller_user_id=$1 AND title=(SELECT title FROM videobot_listings WHERE listing_id=$2)`,
  [owner,'v26nov24invoice']);
 const l=listings.rows.map((r,i)=>({item:i+1,id:r.listing_id,rev:r.revision,status:r.status,title:r.title,
   paid:Number(r.paid_count),invoicePaid:Number(r.invoice_paid_count),invoiceOrders:Number(r.invoice_order_count),
   publicReceipts:Number(r.public_receipt_count),receipts:Number(r.receipt_count),
   postedMessages:(r.post_ids??[]).map(Number),created:r.created_at}));
 const state=sessions.rows[0]?.state??{};
 console.log('VIDEO_OWNER_LISTING_CLASSIFICATION='+JSON.stringify({
    totalFetched:l.length,sameTitleAsAnchored:Number(sameTitle.rows[0].n),
    rows:l,session:{revision:sessions.rows[0]?.revision??null,screen:state.screen??null,
     draftMode:state.draft?.mode??null,hasDraftVideo:!!state.draft?.paidVideo,
     pendingDraft:!!state.pendingVideoDraft,publishing:state.publishing??null,
     hasAlbum:!!state.albumMessageId}}));
}finally{await pool.end()}
JS
